mapper.select:
SELECT PBC_UUID AS pbcUuid, PARTY_ORG_CODE AS partyOrgCode, PARTY_ORG_NAME AS partyOrgName, PARTY_PROD_ID AS partyProdId, PARTY_PROD_NAME AS partyProdName, PARTY_PROD_TYPE AS partyProdType, ASSET_CODE AS assetCode, ASSET_TYPE AS assetType, STATUS AS status, CREATE_USER AS createUser, CREATE_DEPT AS createDept, CREATE_TIME AS createTime, UPDATE_USER AS updateUser, UPDATE_TIME AS updateTime FROM PBC_SPE_COUNTER_PARTY
AND PARTY_ORG_NAME LIKE CONCAT('%',#{partyOrgName,jdbcType=VARCHAR},'%')
AND PARTY_PROD_NAME LIKE CONCAT('%',#{partyProdName,jdbcType=VARCHAR},'%')
AND ASSET_CODE LIKE CONCAT('%',#{assetCode,jdbcType=VARCHAR},'%')
AND ASSET_TYPE = #{assetType,jdbcType=VARCHAR}
AND PARTY_PROD_TYPE = #{partyProdType,jdbcType=VARCHAR}
AND STATUS = #{status,jdbcType=VARCHAR}
ORDER BY UPDATE_TIME DESC

mapper.insert:
INSERT INTO PBC_SPE_COUNTER_PARTY ( PBC_UUID, PARTY_ORG_CODE, PARTY_ORG_NAME, PARTY_PROD_ID, PARTY_PROD_NAME, PARTY_PROD_TYPE, ASSET_CODE, ASSET_TYPE, STATUS, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT PBC_UUID, PARTY_ORG_CODE, PARTY_ORG_NAME, PARTY_PROD_ID, PARTY_PROD_NAME, PARTY_PROD_TYPE, ASSET_CODE, ASSET_TYPE, STATUS, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME FROM ( select TEMP.* from (
select #{item.pbcUuid, jdbcType=VARCHAR } PBC_UUID, #{item.partyOrgCode, jdbcType=VARCHAR } PARTY_ORG_CODE, #{item.partyOrgName, jdbcType=VARCHAR } PARTY_ORG_NAME, #{item.partyProdId, jdbcType=VARCHAR } PARTY_PROD_ID, #{item.partyProdName, jdbcType=VARCHAR } PARTY_PROD_NAME, #{item.partyProdType, jdbcType=VARCHAR } PARTY_PROD_TYPE, #{item.assetCode, jdbcType=VARCHAR } ASSET_CODE, #{item.assetType, jdbcType=VARCHAR } ASSET_TYPE, #{item.status, jdbcType=VARCHAR } STATUS, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME from dual
) TEMP WHERE NOT EXISTS ( SELECT 1 FROM PBC_SPE_COUNTER_PARTY PSCP WHERE PSCP.ASSET_CODE = TEMP.ASSET_CODE ) ) de;
UPDATE PBC_SPE_COUNTER_PARTY AS P, ( select T.* from (
select #{item.pbcUuid, jdbcType=VARCHAR } PBC_UUID, #{item.partyOrgCode, jdbcType=VARCHAR } PARTY_ORG_CODE, #{item.partyOrgName, jdbcType=VARCHAR } PARTY_ORG_NAME, #{item.partyProdId, jdbcType=VARCHAR } PARTY_PROD_ID, #{item.partyProdName, jdbcType=VARCHAR } PARTY_PROD_NAME, #{item.partyProdType, jdbcType=VARCHAR } PARTY_PROD_TYPE, #{item.assetCode, jdbcType=VARCHAR } ASSET_CODE, #{item.assetType, jdbcType=VARCHAR } ASSET_TYPE, #{item.status, jdbcType=VARCHAR } STATUS, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME from dual
) T ) AS TEMP SET P.PBC_UUID = TEMP.PBC_UUID, P.PARTY_ORG_CODE = TEMP.PARTY_ORG_CODE, P.PARTY_ORG_NAME = TEMP.PARTY_ORG_NAME, P.PARTY_PROD_ID = TEMP.PARTY_PROD_ID, P.PARTY_PROD_NAME = TEMP.PARTY_PROD_NAME, P.PARTY_PROD_TYPE = TEMP.PARTY_PROD_TYPE, P.ASSET_TYPE = TEMP.ASSET_TYPE, P.STATUS = TEMP.STATUS, P.CREATE_USER = TEMP.CREATE_USER, P.CREATE_DEPT = TEMP.CREATE_DEPT, P.CREATE_TIME = TEMP.CREATE_TIME, P.UPDATE_USER = TEMP.UPDATE_USER, P.UPDATE_TIME = TEMP.UPDATE_TIME WHERE P.ASSET_CODE = TEMP.ASSET_CODE

